import math


def rose(label, n, a):
    print(label)
    if n % 2 == 1:
        print(f"  n = {n} is odd: {n} petals of length {abs(a)}, drawn once for theta from 0 to pi")
    else:
        print(f"  n = {n} is even: {2 * n} petals of length {abs(a)}, drawn once for theta from 0 to 2pi")


def limacon(label, a, b):
    print(label)
    if a < b:
        t = math.acos(-a / b)
        print(f"  a = {a} < b = {b}: an inner loop, r = 0 at theta = {t:.4f} and {2 * math.pi - t:.4f}")
    elif a == b:
        print(f"  a = b = {a}: a cardioid, with its cusp at theta = pi = {math.pi:.4f}")
    elif a < 2 * b:
        print(f"  b = {b} < a = {a} < 2b = {2 * b}: a dimple, smallest r = {a - b}")
    else:
        print(f"  a = {a} >= 2b = {2 * b}: convex, smallest r = {a - b}")


rose("Example 1 · r = cos 2theta", 2, 1)
rose("Example 2 · r = 3 sin 3theta", 3, 3)
rose("Example 3 · r = cos 3theta", 3, 1)
limacon("Example 5 · r = 1 + cos theta", 1, 1)
limacon("Example 6 · r = 1 + 2cos theta", 1, 2)
limacon("Example 7 · r = 3 + 2cos theta", 3, 2)
limacon("Example 7 · r = 3 + cos theta", 3, 1)

