import math

count = int(input())
for i in range(count):
    parts = input().split()
    p, q = int(parts[1]), int(parts[2])
    if parts[0] == "rose":
        n, a = p, q
        if n % 2 == 1:
            print(f"Problem {i + 1}: rose, {n} petals of length {abs(a)}, theta from 0 to pi")
        else:
            print(f"Problem {i + 1}: rose, {2 * n} petals of length {abs(a)}, theta from 0 to 2pi")
    else:
        a, b = p, q
        if a < b:
            t = math.acos(-a / b)
            print(f"Problem {i + 1}: limacon, inner loop, r = 0 at {t:.4f} and {2 * math.pi - t:.4f}")
        elif a == b:
            print(f"Problem {i + 1}: limacon, cardioid")
        elif a < 2 * b:
            print(f"Problem {i + 1}: limacon, dimple")
        else:
            print(f"Problem {i + 1}: limacon, convex")
